// Flatten a BTCMatic fire delivery into journal columns. The payload is
// { claim_key, rule_id, rule_name, event, trace, outcome? } — the trace
// lists every condition leaf with its value and pass/fail, so the journal
// records WHY the rule fired, not just that it did.
const fire = $json;
const payload = fire.event?.payload ?? {};
const leaves = fire.trace?.leaves ?? fire.trace ?? [];
const traceText = Array.isArray(leaves)
  ? leaves
      .map((l) => `${l.metric}${l.value !== undefined ? ' ' + l.value : ''} ${l.op} ${l.threshold} (${l.passed ? 'pass' : 'fail'}${l.reason ? ': ' + l.reason : ''})`)
      .join('; ')
  : JSON.stringify(leaves);

// The fee gate is a canonical engine metric, so its observed value lives in
// the evaluation trace (not the alert payload).
const feeLeaf = Array.isArray(leaves) ? leaves.find((l) => l.metric === 'fee_next_block') : undefined;

return [{
  json: {
    fired_at: $now.toISO(),
    rule: fire.rule_name ?? fire.rule_id ?? '',
    signal: payload.signal ?? '',
    ticker: payload.ticker ?? '',
    rsi: payload.rsi ?? '',
    price: payload.price ?? '',
    fee_next_block: feeLeaf?.value ?? '',
    trace: traceText,
    claim_key: fire.claim_key ?? '',
    signature_valid: fire.signature_valid === true
  }
}];
